// Fixture for core/ tests: the place of « Louis's Round » on paper (six stations), its PDL source, and the five scripted
// sessions that produce the golden journals (tests/golden/, regenerated by `node tools/core-golden.mjs`).
// Model answers here are fixed canned answers (docs/sdlc.md §3): they stand for what a tier returned, nothing more.
import { readFileSync } from 'node:fs';
import { createSession } from '../core/session.js';
import { createPaperWorld } from '../core/paper-world.js';
import { parseSource, principlesOf, compilePack, attachCompiled, approve } from '../core/source.js';
import { loadPack, loadLibrary } from '../tools/pack-check.mjs';
import { parseTokens } from '../core/pdl.js';

const MATIERES = JSON.parse(readFileSync(new URL('../src/matieres.json', import.meta.url), 'utf8'));

export const LOUIS = {
  langs: ['fr', 'en'], scene: 'path', start: 'trailhead', author: 'toine',
  stations: [
    { id: 'trailhead', pos: [0, 0], heading: 0, reach_m: 2.5, next: ['path'] },
    { id: 'path', pos: [0, 40], heading: 5, reach_m: 2.5, next: ['pines'] },
    { id: 'pines', pos: [5, 80], heading: 10, reach_m: 2.5, next: ['platiere'] },
    { id: 'platiere', pos: [10, 130], heading: 8, reach_m: 3, next: ['hide-edge'] },
    { id: 'hide-edge', pos: [12, 165], heading: 4, reach_m: 2.5, next: ['hide'] },
    { id: 'hide', pos: [14, 178], heading: 0, reach_m: 2, next: [] },
  ],
  things: [
    { id: 'pine-mark', name: 'pine with a blue mark', pos: [1.5, 41], size_m: 0.6 },
    { id: 'pine-3', name: 'sick pine', pos: [6.5, 81.5], size_m: 0.7 },
    { id: 'hide', name: 'wooden hide', pos: [14, 182], size_m: 3 },
    { id: 'jay-oak', name: 'old oak', pos: [-30, 160], size_m: 1.2 },
  ],
  place: { fog: 0.03, lamp: false, sun_height: 2, weather: 'veil' },
  camera: { battery: 0.3, drain_per_s: 0.0005 },
  vocab: {
    materials: Object.keys(MATIERES.recettes),
    cues: { jay_alarm: { recipe: 'jay_alarm' }, branch_snap: { recipe: 'branch_snap' }, steps_leaves: { recipe: 'steps_leaves' } },
    lines: {
      battery_low: { fr: 'La batterie est presque morte. On n’a plus longtemps.', en: 'Battery’s nearly dead. We don’t have long.' },
      jay_stop: { fr: 'Le geai. Je ne bouge plus.', en: 'The jay. I’m not moving.' },
      commit_recall: { fr: 'Tu m’as dit de m’arrêter si le geai criait. Je m’arrête.', en: 'You told me to stop if the jay called. I’m stopping.' },
      snap_line: { fr: 'Une branche. Quelqu’un ?', en: 'A branch. Someone there?' },
      mark_line: { fr: 'Du bleu. Louis marquait les arbres malades en bleu.', en: 'Blue. Louis marked the sick trees in blue.' },
    },
  },
};

// A small source in the pack grammar (docs/pdl-spec.md §2), for the fixture place: a gauge, a rule on its word, a tendency
// that mentions it, an explicit absolute.
export const SOURCE = `# fixture-hide — rules near the hide (fixture)
@kind rules  @layer base  @author toine  @lang en  @scope story  @horizon story

## gauges
gauge disturbance "how much the animals near the hide have been disturbed": rises sound(branch_snap) by 0.5; rises said.loud by 0.3 if near(body, hide, 30); fades 0.1/min; words 0.3 0.6 {disturbance}

## rules
when gauge(disturbance, high) -> say(jay_stop), body.posture(0.5) {hide.quiet}
!! never go(hide) if not scene(platiere) {sam.hide-early}

## principles
~0.8 When the disturbance is high, she whispers and stops moving. {sam.hush}
? Would she go closer to the hide? -- only once the disturbance is low again. {sam.closer}
`;

const M = (id, tier) => ({ kind: 'model', id, tier });
export const TRANSLATE = M('translator', 'translate'), STAGE = M('stager', 'stage'), BACKGROUND = M('keeper', 'background');
export const ENGINE = { kind: 'engine', id: 'page' }, CREATOR = { kind: 'creator', id: 'toine', layer: 'base' };

export function newSession(seed = 7) { return createSession({ scene: LOUIS, seed, executor: createPaperWorld() }); }
const say = (fr, en, tone = 'dry') => ({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'say', line: { fr, en }, tone } });
const go = (s, to) => s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'go', to: 'station:' + to } });

/* ---------------------------------------------------------------- the five golden sessions, one per pillar */
export const SCENARIOS = {
  /* Pillar 1: every change is a validated transaction; repairs and refusals are recorded. */
  'p1-transactions'(s) {
    go(s, 'path');
    const i = s.submit({ author: TRANSLATE, horizon: 'now', kind: 'intent', body: { text: 'regarde la marque sur ce pin', lang: 'fr', verb: 'look', target: 'thing:pine-mark' } }, { timings: { model_ms: 310 } });
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'look' }, cause: { tx: i.seq } }, { timings: { model_ms: 1900 } });   // target completed from the intent
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'say', ref: 'mark_line', tone: 'dry' }, cause: { tx: i.seq } });
    s.submit({ author: STAGE, horizon: 'story', kind: 'fact', body: { subject: 'louis', predicate: 'marked_sick_trees', value: 'blue', source: 'the mark on the pine' }, cause: { tx: i.seq } });
    const k = s.submit({ author: TRANSLATE, horizon: 'now', kind: 'intent', body: { text: 'fais un petit cairn, à hauteur de genou', lang: 'fr', verb: 'make', params: { size_m: 0.5 } } });
    s.submit({ author: STAGE, horizon: 'scene', kind: 'effect', cause: { tx: k.seq }, body: { op: 'thing.place', id: 'cairn', name: 'small cairn', mass_kg: 12, offset: [0.4, 6],
      shapes: [{ shape: 'ball', p: [0, 0.3, 0], size: [1.4, 0.6, 1.2], material: 'gres', color: '#9a9488' }, { shape: 'ball', p: [0, 0.9, 0], size: [1, 0.6, 0.9], material: 'gres' }, { shape: 'ball', p: [0, 1.5, 0], size: [0.6, 0.6, 0.6], material: 'marble' }] } });
    const t = s.submit({ author: TRANSLATE, horizon: 'now', kind: 'intent', body: { text: 'touche le cairn', lang: 'fr', verb: 'touch', target: 'thing:cairn' } });
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', cause: { tx: t.seq }, body: { op: 'touch', target: 'thing:hide' } });   // out of reach: replaced by the intent's target
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'fly', height: 3 } });                                         // unknown op
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'approach', target: 'thing:pine-mark' } });                    // reserved for v2
    s.submit({ author: STAGE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'jay_alarm', volume: 1 } });              // unknown field
    s.submit({ author: { kind: 'player', id: 'player' }, horizon: 'now', kind: 'act', body: { op: 'stop' } });                         // a player never acts
    s.submit({ author: STAGE, horizon: 'story', kind: 'act', body: { op: 'go', to: 'station:platiere' } });                           // horizon repaired, one station at a time
    s.checkpoint();
  },
  /* Pillar 2: now, scene and story transactions in one session, with their expiry. */
  'p2-horizons'(s) {
    s.submit({ author: STAGE, horizon: 'now', kind: 'effect', ttl: 4, body: { op: 'thing.place', id: 'breath', name: 'breath in the cold', offset: [0, 0.6], shapes: [{ shape: 'ball', p: [0, 1.4, 0], size: [0.3, 0.2, 0.3], color: '#d8dde0' }] } });
    s.submit({ author: STAGE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'steps_leaves', gain: 0.3 } });
    s.submit({ author: BACKGROUND, horizon: 'scene', kind: 'effect', body: { op: 'place.set', fog: 0.05 } });
    s.submit({ author: BACKGROUND, horizon: 'scene', kind: 'fact', body: { subject: 'sam', predicate: 'hesitates_at', value: 'trailhead', certainty: 0.8 } });
    s.submit({ author: BACKGROUND, horizon: 'story', kind: 'fact', body: { subject: 'louis', predicate: 'last_seen', value: 'the hide', certainty: 0.6 } });
    s.advance(5);                                                   // the breath (now, ttl 4) is gone
    s.checkpoint();
    go(s, 'path');
    s.submit({ author: ENGINE, horizon: 'now', kind: 'effect', body: { op: 'scene.start', id: 'sentier' } });   // the scene fog and fact end
    s.advance(1);
    s.checkpoint();
  },
  /* Pillar 3: a rule written by a model mid-session (token form), firing later in code; the cycle guard. */
  'p3-model-rule'(s) {
    s.modelCall({ tier: 'background', purpose: 'rules for the platiere', character: 'sam', timings: { model_ms: 8200 } });
    const [rule] = parseTokens(`m:keeper/background story rule id=jay.stop on.ev=sound.played on.m.cue=jay_alarm
  if near a=body b=thing:hide within=20
  then now act.stop
  then now act.say ref=jay_stop tone=whisper`);
    s.submit(rule);
    s.submit({ author: BACKGROUND, horizon: 'story', kind: 'rule', body: { id: 'echo.self', when: { event: 'said' }, then: [{ horizon: 'now', kind: 'act', body: { op: 'say', ref: 'snap_line' } }] } });   // refused: self-trigger
    s.submit({ author: BACKGROUND, horizon: 'scene', kind: 'rule', body: { id: 'echo.a', when: { event: 'said', match: { ref: 'mark_line' } }, then: [{ horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'branch_snap', at: 'thing:jay-oak' } }], limits: { max_fires: 5 } } });
    s.submit({ author: BACKGROUND, horizon: 'scene', kind: 'rule', body: { id: 'echo.b', when: { event: 'sound.played', match: { cue: 'branch_snap' } }, then: [{ horizon: 'now', kind: 'act', body: { op: 'say', ref: 'mark_line' } }], limits: { max_fires: 5 } } });
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'say', ref: 'mark_line' } });   // a → b → a is cut: cycle
    for (const st of ['path', 'pines', 'platiere', 'hide-edge']) { s.advance(30); go(s, st); }
    s.submit({ author: ENGINE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'jay_alarm', at: 'thing:jay-oak' } });   // no model call: the rule fires
    // a gauge from PDL source: two sounds near the hide make it high; its rule fires; a model call sees its word
    s.loadPrinciples(compileSource(SOURCE));
    s.submit({ author: ENGINE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'branch_snap' } });
    s.submit({ author: ENGINE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'branch_snap' } });
    s.modelCall({ tier: 'stage', purpose: 'answer the player', character: 'sam' });
    s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'go', to: 'station:hide' } });   // !! sam.hide-early
    s.checkpoint();
  },
};
export function compileSource(text) {
  const d = parseSource(text, { file: 'tests/fixture.pdl' });
  if (d.errors.length) throw new Error(JSON.stringify(d.errors));
  return principlesOf(d, { ctx: { things: new Set(LOUIS.things.map(t => t.id)), clocks: { battery: 'camera.battery' } } }).principles;
}

/* ---------------------------------------------------------------- the real pack: stories/louis-round */
const ROOT = new URL('../', import.meta.url).pathname;
export function louisPack() {
  const pack = loadPack(ROOT + 'stories/louis-round'), library = loadLibrary(ROOT + 'patterns');   // store adapter (I/O)
  const c = compilePack(pack, library);
  // pack build: a model compiled one prose absolute (canned answer), the creator approved it
  const harm = c.principles.find(p => p.id === 'sam.never.harm');
  attachCompiled(harm, { forbid: { kind: 'effect', op: 'sound.play', fields: { at: 'thing:terrier' } } }, { by: 'model:compiler' });
  approve(harm, 'creator:toine');
  return c;
}
/* Pillars 8, 9, 10 on the real pack: two layers merged with provenance, explicit and pattern rules registered, the jay
   commitment made at the third station and kept at the fifth, an absolute rejecting, a model call with principles in scope. */
SCENARIOS['p8-louis-pack'] = (s, c) => {
  s.loadPrinciples(c.principles);
  s.start();
  const P = { kind: 'player', id: 'player' }, T = TRANSLATE;
  const call = s.modelCall({ tier: 'stage', purpose: 'greet', character: 'sam', loop: 'scene', status: 'done', timings: { model_ms: 2100 } });
  s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'say', ref: 'greet.first' } }, { loop: 'scene', latency_ms: 2100 });
  go(s, 'first-mark');
  const i = s.submit({ author: T, horizon: 'now', kind: 'intent', body: { text: 'regarde ce trait orange', lang: 'fr', verb: 'look', target: 'thing:marque-1' } }, { loop: 'now', latency_ms: 240 });
  s.submit({ author: T, horizon: 'now', kind: 'act', cause: { tx: i.seq }, body: { op: 'look', target: 'thing:marque-1' } }, { loop: 'now', latency_ms: 260 });   // louis-marks.sign-read.1
  go(s, 'fallen-pine');
  const k = s.submit({ author: T, horizon: 'now', kind: 'intent', body: { text: 'si le geai crie, arrête-toi et couche-toi', lang: 'fr', verb: 'commit', class: 'jay', condition: 'the jay calls', behaviour: 'stop and lie down', commit: 'c.jay' } }, { loop: 'now', latency_ms: 900 });
  s.submit({ author: STAGE, horizon: 'now', kind: 'act', cause: { tx: k.seq }, body: { op: 'say', ref: 'commit.amend' } }, { loop: 'scene', latency_ms: 2600 });
  s.submit({ author: P, horizon: 'story', kind: 'fact', cause: { tx: k.seq, commit: 'c.jay' }, body: { subject: 'sam', predicate: 'promised', value: 'stop and crouch if the jay calls (not lie down)', commit: { id: 'c.jay', party: 'sam', status: 'amended', strength: 'hard' } } });
  s.submit({ author: P, horizon: 'story', kind: 'rule', cause: { tx: k.seq, commit: 'c.jay' }, body: { id: 'c.jay', commit: 'c.jay', when: { event: 'sound.played', match: { cue: 'jay.alarm' } },
    then: [{ horizon: 'now', kind: 'act', body: { op: 'stop' } }, { horizon: 'now', kind: 'act', body: { op: 'posture', height: 0.55 } }, { horizon: 'now', kind: 'act', body: { op: 'say', ref: 'commit.keeping' } }] } });
  s.submit({ author: STAGE, horizon: 'now', kind: 'effect', body: { op: 'sound.play', cue: 'bracken.rustle', at: 'thing:terrier' } }, { loop: 'scene', latency_ms: 3100 });   // !! sam.never.harm
  go(s, 'platiere');
  s.submit({ author: STAGE, horizon: 'now', kind: 'act', body: { op: 'go', to: 'station:approach', via: 'tape' } });   // r.jay-first → c.jay kept
  s.advance(400);                                                  // battery under half: battery-clock.half
  s.audit([{ principle: 'sam.voice.dry', ref_seq: call.seq + 1, relevant: true, respected: true, judge: { kind: 'model', id: 'judge', tier: 'background' } },
    { principle: 'sam.word.keeps', ref_seq: s.journal.entries.find(e => e.type === 'rule' && e.rule === 'c.jay').seq, relevant: true, respected: true, judge: { kind: 'model', id: 'judge', tier: 'background' } }]);
  s.checkpoint();
};
export function runScenario(name, seed = 7) {
  if (name === 'p8-louis-pack') { const c = louisPack(); const s = createSession({ scene: c.scene, seed, executor: createPaperWorld() }); SCENARIOS[name](s, c); return s; }
  const s = newSession(seed); SCENARIOS[name](s); return s;
}
